// 查询飞书 ASIN 主表中状态=待处理 且 商品URL 不为空的记录
const https = require('https');
const APP_ID = 'cli_a9460d39a5395bdd';
const APP_SECRET = 'VL57clXcR2kFndvW4Pcj86A3hE6EOSiQ';
const APP_TOKEN = 'TaHNbaexlapD6IsV6escowAknrd';
const TABLE_ID = 'tblPl7Z8o4mTy4La';
const SKU_TABLE_ID = 'tblEOeeD4HARuHuI';

function post(path, body, token) {
  return new Promise((resolve, reject) => {
    const s = JSON.stringify(body);
    const h = {'Content-Type':'application/json','Content-Length':Buffer.byteLength(s)};
    if (token) h['Authorization'] = 'Bearer ' + token;
    const req = https.request({hostname:'open.feishu.cn',path,method:'POST',headers:h},(res)=>{
      let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve(JSON.parse(d)));
    });
    req.on('error',reject); req.write(s); req.end();
  });
}
function put(path, body, token) {
  return new Promise((resolve, reject) => {
    const s = JSON.stringify(body);
    const h = {'Content-Type':'application/json','Content-Length':Buffer.byteLength(s),'Authorization':'Bearer '+token};
    const req = https.request({hostname:'open.feishu.cn',path,method:'PUT',headers:h},(res)=>{
      let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve(JSON.parse(d)));
    });
    req.on('error',reject); req.write(s); req.end();
  });
}

// Get token
const tr = await post('/open-apis/auth/v3/tenant_access_token/internal',{app_id:APP_ID,app_secret:APP_SECRET},null);
if (tr.code !== 0) throw new Error('Token failed');
const token = tr.tenant_access_token;

// Search pending records
const sr = await post('/open-apis/bitable/v1/apps/'+APP_TOKEN+'/tables/'+TABLE_ID+'/records/search',{
  filter:{conjunction:'and',conditions:[
    {field_name:'任务状态',operator:'is',value:['待处理']},
    {field_name:'商品URL',operator:'isNotEmpty',value:[]}
  ]},page_size:5
},token);

const records = sr.data?.items || [];
if (records.length === 0) return [{json:{pending:0,skipped:true}}];

// Mark as 抓取中 to avoid double-processing
for (const rec of records) {
  await put('/open-apis/bitable/v1/apps/'+APP_TOKEN+'/tables/'+TABLE_ID+'/records/'+rec.record_id,
    {fields:{'任务状态':'抓取中'}},token);
}

return records.map(rec => ({json:{
  app_token:APP_TOKEN, table_id:TABLE_ID, sku_table_id:SKU_TABLE_ID,
  record_id:rec.record_id, url:(()=>{const u=rec.fields?.['商品URL'];return typeof u==='object'?(u.link||u.text||''):(u||'');})(), feishu_token:token
}}));

const {execSync}=require('child_process');
const d=.first().json;
if(!d.url)throw new Error('URL empty');
let result;
try{
  const raw=execSync('python3 /Users/panjinlong/Documents/agent-master/n8n-automation/scripts/amazon_scraper.py "'+d.url.replace(/"/g,'\\"')+'"',{timeout:50000,encoding:'utf8'});
  const line=raw.trim().split('\n').find(l=>l.startsWith('{'));
  result=JSON.parse(line||raw.trim());
}catch(e){throw new Error('scrape error: '+e.message.substring(0,200));}
if(result.error)throw new Error(result.error);
const bullets=(result.bullets||[]).map((b,i)=>i+1+'. '+b).join('\n');
return [{json:{...d,asin:result.asin||'',title:result.title||'',brand:result.brand||'',bullets_text:bullets,variants:result.variants||[],size_chart:result.size_chart||''}}];

const https=require('https');
const d=$input.first().json;
function req(path,method,body,token){return new Promise((resolve,reject)=>{
  const s=JSON.stringify(body);
  const opts={hostname:'open.feishu.cn',path,method,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token,'Content-Length':Buffer.byteLength(s)}};
  const r=https.request(opts,(res)=>{let d='';res.on('data',c=>d+=c);res.on('end',()=>resolve(JSON.parse(d)));});
  r.on('error',reject);r.write(s);r.end();
});}
const fields={'ASIN':d.asin,'产品名称':d.title,'现有标题':d.title,'Bullet原版(1-5)':d.bullets_text,'任务状态':'待审核'};
if(d.size_chart)fields['尺码数据']=d.size_chart;
const r=await req('/open-apis/bitable/v1/apps/'+d.app_token+'/tables/'+d.table_id+'/records/'+d.record_id,'PUT',{fields},d.feishu_token);
if(r.code!==0)throw new Error('write failed: '+JSON.stringify(r).substring(0,150));
const variants=d.variants||[];
if(variants.length>0){
  const recs=variants.slice(0,20).map(v=>({fields:{'SKU ID':d.asin+'-'+v,'变体名称':v}}));
  await req('/open-apis/bitable/v1/apps/'+d.app_token+'/tables/'+d.sku_table_id+'/records/batch_create','POST',{records:recs},d.feishu_token);
}
return [{json:{record_id:d.record_id,asin:d.asin,variants_count:variants.length,done:true}}];
